WITH UserBadges AS (SELECT U.Id AS UserId, U.Reputation, COUNT(B.Id) AS BadgeCount, GROUP_CONCAT(B.Name, ', ') AS BadgeNames FROM Users AS U LEFT JOIN Badges AS B ON U.Id = B.UserId GROUP BY U.Id, U.Reputation), RecentPosts AS (SELECT P.Id AS PostId, P.OwnerUserId, P.CreationDate, P.Title, P.ViewCount, ROW_NUMBER() OVER (PARTITION BY P.OwnerUserId ORDER BY P.CreationDate DESC NULLS FIRST) AS RowNum FROM Posts AS P WHERE P.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '30' DAYS), ClosedPosts AS (SELECT PH.PostId, PH.CreationDate, H.Name AS HistoryType FROM PostHistory AS PH JOIN PostHistoryTypes AS H ON PH.PostHistoryTypeId = H.Id WHERE PH.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '30' DAYS AND H.Name = 'Post Closed') SELECT U.DisplayName, UB.BadgeCount, COALESCE(UB.BadgeNames, 'No badges') AS BadgeNames, RP.Title AS RecentPostTitle, RP.ViewCount AS RecentPostViews, CP.CreationDate AS ClosedPostDate, CP.HistoryType AS ClosedPostHistoryType FROM Users AS U LEFT JOIN UserBadges AS UB ON U.Id = UB.UserId LEFT JOIN RecentPosts AS RP ON U.Id = RP.OwnerUserId AND RP.RowNum = 1 LEFT JOIN ClosedPosts AS CP ON U.Id = CP.PostId WHERE U.Reputation > 1000 ORDER BY U.Reputation DESC NULLS FIRST, RP.ViewCount DESC NULLS FIRST LIMIT 10